const toId = (v) => {
  const s = String(v || '').trim();
  const m = s.match(/linkedin\.com\/company\/([^/?#]+)/i);
  return (m ? m[1] : s).replace(/\/$/, '').toLowerCase();
};
const done = new Set();
for (const r of $('Read Already Researched').all()) {
  const id = toId(r.json.public_identifier || r.json.company_url);
  if (id) done.add(id);
}
const seen = new Set();
const out = [];
for (const r of $('Read Companies to Research').all()) {
  const url = r.json.company_url || r.json['Company URL'] || '';
  const id = toId(url);
  if (!id || done.has(id) || seen.has(id)) continue;
  seen.add(id);
  out.push({ json: { company_url: url, identifier: id } });
}
return out;

const src = $('Loop Over Companies').item.json;
const c = $json || {};
const locs = Array.isArray(c.locations) ? c.locations : [];
const hq = locs.find(l => l.is_headquarter) || locs[0] || {};
const offices = locs.map(l => [l.city, l.country].filter(Boolean).join(', ')).filter(Boolean);
const range = c.employee_count_range || {};
const growth = (c.insights && c.insights.employeesCount && Array.isArray(c.insights.employeesCount.growthGraph)) ? c.insights.employeesCount.growthGraph : [];
const g = (m) => { const x = growth.find(v => v.monthRange === m); return x ? x.growthPercentage : ''; };
const spec = c.specialities || c.specialties || c.activities || [];
return { json: {
  company_url: src.company_url,
  public_identifier: c.public_identifier || src.identifier,
  name: c.name || '',
  website: c.website || '',
  industry: Array.isArray(c.industry) ? c.industry.join(', ') : (c.industry || ''),
  employee_count: c.employee_count || '',
  employee_range: range.from ? `${range.from}-${range.to || ''}` : '',
  hq_city: hq.city || '',
  hq_country: hq.country || '',
  offices: offices.join('; '),
  office_count: offices.length || '',
  founded: c.foundation_date || '',
  followers: c.followers_count || '',
  headcount_growth_6m: g(6),
  headcount_growth_12m: g(12),
  headcount_growth_24m: g(24),
  avg_tenure: (c.insights && c.insights.employeesCount && c.insights.employeesCount.averageTenure) || '',
  specialties: Array.isArray(spec) ? spec.join(', ') : String(spec || ''),
  tagline: c.tagline || '',
  description: String(c.description || '').slice(0, 400),
  found: !!c.name
} };

const c = $('Normalize Company').item.json;
const threshold = $('ICP Config').first().json.score_threshold;
let r = { score: 0, reason: c.found ? 'parse error' : 'company not found' };
try {
  let raw = $json.content?.[0]?.text || '{}';
  raw = raw.trim().replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/i, '').trim();
  r = JSON.parse(raw);
} catch (e) {}
const { found, ...row } = c;
return { json: { ...row, icp_score: r.score || 0, icp_reason: r.reason || '', icp_fit: (r.score || 0) >= threshold ? 'yes' : 'no', researched_at: new Date().toISOString() } };
